'use strict';

// MODULES //

var ndarraylike2scalar = require( '@stdlib/ndarray-base-ndarraylike2scalar' );
var getShape = require( '@stdlib/ndarray-base-shape' );
var getStrides = require( '@stdlib/ndarray-base-strides' );
var getStride = require( '@stdlib/ndarray-base-stride' );
var getOffset = require( '@stdlib/ndarray-base-offset' );
var getData = require( '@stdlib/ndarray-base-data-buffer' );
var strided = require( '@stdlib/blas-ext-base-svander' ).ndarray;


// MAIN //

/**
* Generates a single-precision floating-point Vandermonde matrix.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a two-dimensional output ndarray.
*     -   a zero-dimensional ndarray specifying the mode.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* var Float32Vector = require( '@stdlib/ndarray-vector-float32' );
* var zeros = require( '@stdlib/ndarray-zeros' );
* var scalar2ndarray = require( '@stdlib/ndarray-from-scalar' );
*
* var x = new Float32Vector( [ 1.0, 2.0, 3.0 ] );
* var out = zeros( [ 3, 3 ], {
*     'dtype': 'float32'
* });
*
* var mode = scalar2ndarray( 1, {
*     'dtype': 'float32'
* });
*
* var v = svander( [ x, out, mode ] );
* // returns <ndarray>[ [ 1.0, 1.0, 1.0 ], [ 1.0, 2.0, 4.0 ], [ 1.0, 3.0, 9.0 ] ]
*
* var bool = ( v === out );
* // returns true
*/
function svander( arrays ) {
	var mode;
	var out;
	var sh;
	var so;
	var x;

	x = arrays[ 0 ];
	out = arrays[ 1 ];
	mode = ndarraylike2scalar( arrays[ 2 ] );

	sh = getShape( out, false );
	so = getStrides( out, false );

	strided( mode, sh[ 0 ], sh[ 1 ], getData( x ), getStride( x, 0 ), getOffset( x ), getData( out ), so[ 0 ], so[ 1 ], getOffset( out ) ); // eslint-disable-line max-len
	return out;
}


// EXPORTS //

module.exports = svander;
